ed></label></div><div class="col-4"><label>Stock<input class="form-control" name="variants[{{ $loop->index }}][stock]" value="{{ $variant?->stock ?? 0 }}" type="number" min="0" required></label></div></div>@endforeach</div><button type="button" class="btn btn-sm btn-outline-secondary add-variant">Add variant</button><div class="form-check my-3"><input class="form-check-input" type="checkbox" name="active" value="1" id="active-{{ $product?->id ?? 'new' }}" @checked($product?->active)><label class="form-check-label" for="active-{{ $product?->id ?? 'new' }}">Publish product (requires owned/licensed photography and verified details)</label></div><button class="btn btn-primary">Save product</button></form></div></div>@endforeach
